&lt;b&gt;&lt;i&gt;Les &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Magiques.html&quot; title=&quot;Les armes magiques&quot;&gt;armes magiques&lt;/a&gt; poss&#232;dent &#233;galement un &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Magiques.html#BONUSALTERATION&quot; title=&quot;Les armes magiques&quot;&gt;bonus d&#39;alt&#233;ration&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Propri&#233;t&#233;s_sp&#233;ciales_des_armures_et_boucliers_magiques_6&quot;&gt; Propri&#233;t&#233;s sp&#233;ciales des armures et boucliers magiques &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Propri&#233;t&#233;s_ajoutant_un_prix_sp&#233;cifique_0&quot;&gt;Propri&#233;t&#233;s ajoutant un prix sp&#233;cifique&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Propri&#233;t&#233;s_ajoutant_un_bonus_de_+B_1&quot;&gt;Propri&#233;t&#233;s ajoutant un bonus de +1&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Propri&#233;t&#233;s_ajoutant_un_bonus_de_+C_2&quot;&gt;Propri&#233;t&#233;s ajoutant un bonus de +2&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Propri&#233;t&#233;s_ajoutant_un_bonus_de_+D_3&quot;&gt;Propri&#233;t&#233;s ajoutant un bonus de +3&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Propri&#233;t&#233;s_ajoutant_un_bonus_de_+E_4&quot;&gt;Propri&#233;t&#233;s ajoutant un bonus de +4&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Propri&#233;t&#233;s_ajoutant_un_bonus_de_+F_5&quot;&gt;Propri&#233;t&#233;s ajoutant un bonus de +5&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;Les armures et boucliers magiques offrent &#224; leur utilisateur une protection suppl&#233;mentaire, sous la forme d’un bonus d’alt&#233;ration (de +5 au maximum) qui s’ajoute au bonus &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; de l’objet lui-m&#234;me. Les bonus d’une armure, d’un bouclier et de leur magie respective sont cumulatifs. Toutes les armures et tous les boucliers magiques sont des versions &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Armuresmaitre.html&quot; title=&quot;armure de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt;, leur malus d’armure aux tests est ainsi r&#233;duit de 1.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 16px 16px&quot;&gt;
&lt;div style=&quot;border: 1px solid #4b3124; padding: 4px&quot;&gt;
&lt;center&gt;
&lt;table CLASS=&quot;tablo centre&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PRIXBONUSDALTERATION&quot; href=&quot;#PRIXBONUSDALTERATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt; Prix des bonus d&#39;alt&#233;ration des armures et des boucliers&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Bonus d&#39;alt&#233;ration&lt;/td&gt;&lt;td&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;+1 &lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;+2 &lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;+3 &lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;+4 &lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;+5 &lt;/td&gt;&lt;td&gt;25 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;+6&lt;sup&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#NOTE1&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;1&lt;/a&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;+7&lt;sup&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#NOTE1&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;1&lt;/a&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;49 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;+8&lt;sup&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#NOTE1&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;1&lt;/a&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;64 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;+9&lt;sup&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#NOTE1&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;1&lt;/a&gt;&lt;/sup&gt; &lt;/td&gt;&lt;td&gt;81 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;+10&lt;sup&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#NOTE1&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;1&lt;/a&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;100 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;note&quot;&gt;&lt;td COLSPAN=&quot;2&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;NOTE1&quot; href=&quot;#NOTE1&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;i&gt;(1) Le bonus num&#233;rique effectif de l’armure ou du bouclier ne peut &lt;br /&gt; &#234;tre sup&#233;rieur &#224; +5. Utilisez ces lignes pour d&#233;terminer le prix des&lt;br /&gt; armures et des boucliers poss&#233;dant des propri&#233;t&#233;s sp&#233;ciales.&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;/div&gt;&lt;/div&gt;
Une armure peut, en plus de son bonus d’alt&#233;ration, poss&#233;der certaines propri&#233;t&#233;s. Celles-ci sont consid&#233;r&#233;es comme un bonus suppl&#233;mentaire pour ce qui est du prix de l’armure, m&#234;me si elles n’ont aucune influence sur la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;. Une armure ne peut jamais avoir un bonus total (bonus d’alt&#233;ration plus bonus li&#233; &#224; ses propri&#233;t&#233;s, y compris celles qui proviennent des aptitudes du personnage et des sorts) sup&#233;rieur &#224; +10. Toute armure poss&#233;dant une propri&#233;t&#233; sp&#233;ciale doit avoir au moins un bonus d’alt&#233;ration de +1.&lt;br /&gt;&lt;br /&gt;Les armures et les boucliers peuvent &#234;tre fabriqu&#233;s dans un mat&#233;riau inhabituel. Lancez 1d100 : sur un r&#233;sultat de 01–95, l’objet est d’un mat&#233;riau standard et, sur 96–100, il est fait d’un mat&#233;riau sp&#233;cial (voir la Section &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;Les mat&#233;riaux sp&#233;ciaux&lt;/a&gt;&quot;).&lt;br /&gt;&lt;br /&gt;M&#234;me si l’armure est accompagn&#233;e de bottes, de gantelets ou d’un heaume, ces parties peuvent &#234;tre &#233;chang&#233;es contre d’autres objets magiques du m&#234;me type sans nuire &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Niveau de lanceur de sorts des armures et boucliers magiques.&lt;/b&gt; Le niveau de lanceur de sorts d’une armure ou d’un bouclier poss&#233;dant une ou plusieurs propri&#233;t&#233;s sp&#233;ciales est indiqu&#233; dans la description de l’objet. Si l’armure ou le bouclier b&#233;n&#233;ficie seulement d’un &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#BONUSALTERATION&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;bonus d’alt&#233;ration&lt;/a&gt;, son niveau de lanceur de sorts est &#233;gal &#224; trois fois son bonus. Si l’objet poss&#232;de un &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#BONUSALTERATION&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;bonus d’alt&#233;ration&lt;/a&gt; ainsi que des propri&#233;t&#233;s magiques, le plus haut niveau de lanceur de sorts entre les deux est celui qui doit &#234;tre consid&#233;r&#233;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Boucliers.&lt;/b&gt; Le &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#BONUSALTERATION&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;bonus d’alt&#233;ration&lt;/a&gt; d’un bouclier magique se cumule avec le &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#BONUSALTERATION&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;bonus d’alt&#233;ration&lt;/a&gt; d’une armure magique. Le &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#BONUSALTERATION&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;bonus d’alt&#233;ration&lt;/a&gt; du bouclier n’est pas comptabilis&#233; dans le &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; ou de d&#233;g&#226;ts dans le cas d’un coup de bouclier. La propri&#233;t&#233; sp&#233;ciale d’attaque conf&#232;re un &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#BONUSALTERATION&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;bonus d’alt&#233;ration&lt;/a&gt; de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et de d&#233;g&#226;ts avec un bouclier (voir la description de la capacit&#233; sp&#233;ciale &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Attaque.html&quot; title=&quot;attaque (propri&#233;t&#233;)&quot;&gt;attaque&lt;/a&gt;&quot;).&lt;br /&gt;&lt;br /&gt;Il est possible de faire d’un bouclier une arme magique, mais il faut alors ajouter aux co&#251;ts du &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#BONUSALTERATION&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;bonus d’alt&#233;ration&lt;/a&gt; &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; ceux du &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#BONUSALTERATION&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;bonus d’alt&#233;ration&lt;/a&gt; aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et aux d&#233;g&#226;ts.&lt;br /&gt;&lt;br /&gt;De la m&#234;me fa&#231;on que pour les armures, les propri&#233;t&#233;s sp&#233;ciales d’un bouclier sont consid&#233;r&#233;es comme un bonus suppl&#233;mentaire pour ce qui est du prix de l’objet, m&#234;me si elles n’am&#233;liorent pas la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;. Un bouclier ne peut jamais avoir un bonus total (&lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#BONUSALTERATION&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;bonus d’alt&#233;ration&lt;/a&gt; plus bonus du aux propri&#233;t&#233;s) sup&#233;rieur &#224; +10. Tout bouclier poss&#233;dant une propri&#233;t&#233; sp&#233;ciale doit avoir un &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#BONUSALTERATION&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;bonus d’alt&#233;ration&lt;/a&gt; d’au moins +1.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Activation.&lt;/b&gt; Une armure ou un bouclier magique fonctionne en g&#233;n&#233;ral de la m&#234;me mani&#232;re qu’un mod&#232;le normal, offrant &#224; son utilisateur les m&#234;mes avantages. Si l’armure ou le bouclier poss&#232;de une propri&#233;t&#233; qui doit &#234;tre activ&#233;e volontairement, cela se fait le plus souvent par le biais d’un &lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Relatives-Aux-Objets-Magiques.html#OBJETSAMOTDECOMMANDE&quot; title=&quot;R&#232;gles relatives aux objets magiques&quot;&gt;mot de commande&lt;/a&gt; (une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Armures pour les cr&#233;atures de taille inhabituelle.&lt;/b&gt; Le prix des armures con&#231;ues pour les cr&#233;atures non humano&#239;des ou d’une cat&#233;gorie de taille autre que P ou M est diff&#233;rent de celui qui est indiqu&#233; (voir la Section &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures.html#ARMURESINHABITUELLES&quot; title=&quot;Caract&#233;ristiques des armures&quot;&gt;Armures pour cr&#233;atures inhabituelles&lt;/a&gt;&quot;). Le co&#251;t de la qualit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Armuresmaitre.html&quot; title=&quot;armure de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; et de l’alt&#233;ration magique restent les m&#234;mes quelle que soit la taille de l’armure.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt; Propri&#233;t&#233;s sp&#233;ciales des armures et boucliers magiques &lt;a class=&quot;headeranchor&quot; id=&quot;Propri&#233;t&#233;s_sp&#233;ciales_des_armures_et_boucliers_magiques_6&quot; href=&quot;#Propri&#233;t&#233;s_sp&#233;ciales_des_armures_et_boucliers_magiques_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Une armure ou un bouclier ayant une propri&#233;t&#233; sp&#233;ciale doit poss&#233;der un bonus d’alt&#233;ration d’au moins +1. Le modificateur au prix de base des propri&#233;t&#233;s ajoutant un &quot;bonus de +X&quot; doit &#234;tre ajout&#233; &#224; ce bonus minimum de +1.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Propri&#233;t&#233;s ajoutant un prix sp&#233;cifique&lt;a class=&quot;headeranchor&quot; id=&quot;Propri&#233;t&#233;s_ajoutant_un_prix_sp&#233;cifique_0&quot; href=&quot;#Propri&#233;t&#233;s_ajoutant_un_prix_sp&#233;cifique_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche&quot; WIDTH=&quot;100%&quot;&gt;&lt;caption&gt;Propri&#233;t&#233;s ajoutant un prix sp&#233;cifique&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;12%&quot;&gt;Propri&#233;t&#233;&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;11%&quot;&gt;Restrictions&lt;/td&gt;&lt;td WIDTH=&quot;61%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;13%&quot;&gt;Modificateur au prix de base&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Rembourr&#233;e.html&quot; title=&quot;rembourr&#233;e (propri&#233;t&#233;)&quot;&gt;Rembourr&#233;e&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures en tissu et matelass&#233;es&lt;/td&gt;&lt;td&gt;R&#233;duit les d&#233;g&#226;ts de chute.&lt;/td&gt;&lt;td&gt;+1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-Au-Poison.html&quot; title=&quot;r&#233;sistance au poison (propri&#233;t&#233;)&quot;&gt;R&#233;sistance au poison&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +3 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les poisons.&lt;/td&gt;&lt;td&gt;+2 250 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Mim&#233;tisme.html&quot; title=&quot;mim&#233;tisme (propri&#233;t&#233; armure)&quot;&gt;Mim&#233;tisme&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Permet de donner l’apparence de v&#234;tements &#224; l’armure (dissimulant son aura) &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;+2 700 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Focalisation-Mentale.html&quot; title=&quot;focalisation mentale (propri&#233;t&#233;)&quot;&gt;Focalisation mentale&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures interm&#233;diaires&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d&#39;alt&#233;ration de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts.html#TESTCONCENTRATION&quot; title=&quot;Lancer des sorts&quot;&gt;concentration&lt;/a&gt;. Une fois par jour, peut offrir 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;+3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Graisseuse.html&quot; title=&quot;graisseuse (propri&#233;t&#233;)&quot;&gt;Graisseuse&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;+3 750 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Joute.html&quot; title=&quot;joute (propri&#233;t&#233;)&quot;&gt;Joute&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;+3 750 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Ombre.html&quot; title=&quot;ombre (propri&#233;t&#233;)&quot;&gt;Ombre&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;+3 750 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Exp&#233;ditive.html&quot; title=&quot;exp&#233;ditive (propri&#233;t&#233;)&quot;&gt;Exp&#233;ditive&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Trois fois par jour, peut conf&#233;rer un bonus d’alt&#233;ration de +3m aux vitesses de d&#233;placement pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;+4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Impond&#233;rable.html&quot; title=&quot;impond&#233;rable (propri&#233;t&#233;)&quot;&gt;Impond&#233;rable&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Poids-Transportable.html&quot; title=&quot;Poids transportable&quot;&gt;poids transportable&lt;/a&gt; de chaque cat&#233;gorie de charge de 50&#160;%.&lt;/td&gt;&lt;td&gt;+4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Amorphe.html&quot; title=&quot;amorphe (propri&#233;t&#233;)&quot;&gt;Amorphe&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt; et au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre les manœuvres de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt;. Une fois par jour, peut transformer son porteur et lui-m&#234;me en vase pendant 1 minute maximum. Sous forme de vase, diminue la vitesse de d&#233;placement du porteur de 3m, l’emp&#234;che d’effectuer des actions autres que &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;de mouvement&lt;/a&gt;, mais lui permet de se faufiler dans tous les espaces restreints.&lt;/td&gt;&lt;td&gt;+4 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Reposante.html&quot; title=&quot;reposante (propri&#233;t&#233;)&quot;&gt;Reposante&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de profiter des effets d’un repos de 8 heures en seulement 2 heures. L’armure peut-&#234;tre port&#233;e pendant un repos sans rendre le porteur &lt;a class=&quot;pagelink&quot; href=&quot;../&#201;tats pr&#233;judiciables#Fatigu&#233;

Un personnage fatigu&#233; est dans l’incapacit&#233; de courir et de charger/-Il-Subit-Un-Malus-De--2-En-Force-Ainsi-Qu’En-Dext&#233;rit&#233;.-La-Fatigue-Se-Dissipe-Au-Bout-De-Huit-Heures-De-Repos-Total.-Un-Personnage-Fatigu&#233;-Devient-&#201;puis&#233;-D&#232;s-Qu’Il-Fait-Quoi-Que-Ce-Soit-Qui-Causerait-Un-Nouvel-&#201;tat-Fatigu&#233;..html&quot; title=&quot;Fatigu&#233;&quot;&gt;fatigu&#233;&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;+4 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Confortable.html&quot; title=&quot;confortable (propri&#233;t&#233;)&quot;&gt;Confortable&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;L&#39;armure est consid&#233;r&#233;e comme &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Legeres.html&quot; title=&quot;armure l&#233;g&#232;re&quot;&gt;l&#233;g&#232;re&lt;/a&gt; lorsque le porteur dort avec. Pas de malus pour r&#233;sister aux &lt;a class=&quot;pagelink&quot; href=&quot;Dangers-Naturels.html#CHALEUR&quot; title=&quot;Les dangers naturels&quot;&gt;chaleurs extr&#234;mes&lt;/a&gt;. Conf&#232;re les avantages d&#39;une &lt;a class=&quot;pagelink&quot; href=&quot;V&#234;tements.html#Tenue adapt&#233;e au froid&quot; title=&quot;V&#234;tements&quot;&gt;tenue polaire&lt;/a&gt; dans le froid. R&#233;duit le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures.html#MALUSARMURE&quot; title=&quot;Caract&#233;ristiques des armures&quot;&gt;malus d’armure aux tests&lt;/a&gt; de 1.&lt;/td&gt;&lt;td&gt;+5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Corsaires.html&quot; title=&quot;corsaires (propri&#233;t&#233;)&quot;&gt;Corsaires&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;. &#192; chaque fois que le porteur r&#233;cup&#232;re de l’&lt;a class=&quot;pagelink&quot; href=&quot;Pistolier#Audace.html&quot; title=&quot;audace&quot;&gt;audace&lt;/a&gt; ou du &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur#Panache.html&quot; title=&quot;panache&quot;&gt;panache&lt;/a&gt;, le bonus conf&#233;r&#233; est doubl&#233; jusqu’au d&#233;but de son prochain tour.&lt;/td&gt;&lt;td&gt;+5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Discr&#233;tion.html&quot; title=&quot;discr&#233;tion (propri&#233;t&#233;)&quot;&gt;Discr&#233;tion&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Le malus d’armure aux tests ne s’applique pas aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;. Une fois par jour, peut conf&#233;rer un bonus aux &#233;gal au bonus d’alt&#233;ration de l’armure aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; du porteurpendant 1 minute.&lt;/td&gt;&lt;td&gt;+5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Rafale-De-Nuages.html&quot; title=&quot;rafale de nuages (propri&#233;t&#233;)&quot;&gt;Rafale de nuages&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Peut stocker les points de d&#233;g&#226;ts d&#39;&#233;lectricit&#233; subit par le porteur qui peuvent &#234;tre rel&#226;ch&#233;s jusqu&#39;au prochain tour de ce dernier afin d&#39;infliger 1d6 points de d&#233;g&#226;ts d&#39;&#233;lectricit&#233; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;charge-&#201;lectrique.html&quot; title=&quot;D&#233;charge &#233;lectrique&quot;&gt;d&#233;charge &#233;lectrique&lt;/a&gt;&lt;/i&gt;) par tranche de 10 points stock&#233;s.&lt;/td&gt;&lt;td&gt;+5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Ralliement.html&quot; title=&quot;ralliement (propri&#233;t&#233;)&quot;&gt;Ralliement&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de moral de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegardes&lt;/a&gt; contre la terreur de tous les alli&#233;s &#224; 9m ou moins du porteur (s’il poss&#232;de d&#233;j&#224; une capacit&#233; similaire, le bonus passe &#224; +6).&lt;/td&gt;&lt;td&gt;+5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Souffle-Draconique.html&quot; title=&quot;souffle draconique (propri&#233;t&#233;)&quot;&gt;Souffle draconique&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers&lt;/td&gt;&lt;td&gt;Peut stocker les points de d&#233;g&#226;ts d’un type d’&#233;nergie choisi &#224; la fabrication subit par le porteur, chaque tranche de 5 points de d&#233;g&#226;ts d’&#233;nergie stock&#233;s repr&#233;sentant 1 charge. Les charges peuvent &#234;tre d&#233;pens&#233;es pour g&#233;n&#233;rer un c&#244;ne de 4,50m infligeant 1d4 points de d&#233;g&#226;ts du type d’&#233;nergie stock&#233;e par charge d&#233;pens&#233;e (5 maximum).&lt;/td&gt;&lt;td&gt;+5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Lien-Spirituel.html&quot; title=&quot;lien spirituel (propri&#233;t&#233;)&quot;&gt;Lien spirituel&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures interm&#233;diaires&lt;/td&gt;&lt;td&gt;Bonus de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les sorts et effets psychiques de cr&#233;atures intangibles et augmente de 1 le &lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium.html#BONUSSPIRITUEL&quot; title=&quot;Le m&#233;dium&quot;&gt;bonus spirituel&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;+6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Serrurier.html&quot; title=&quot;serrurier (propri&#233;t&#233;)&quot;&gt;Serrurier&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures l&#233;g&#232;res&lt;/td&gt;&lt;td&gt;L&#39;armure peut fonctionner comme des &lt;a class=&quot;pagelink&quot; href=&quot;Outils-De-Cambrioleur-(Objet).html&quot; title=&quot;Outils de cambrioleur&quot;&gt;outils de cambrioleur de ma&#238;tre&lt;/a&gt; discrets et permet au porteur de distribuer son bonus d&#39;alt&#233;ration &#224; ses tests de &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;+6 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Adh&#233;sive.html&quot; title=&quot;adh&#233;sive (propri&#233;t&#233;)&quot;&gt;Adh&#233;sive&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Peut conf&#233;rer une vitesse d’escalade de 6m, &#224; volont&#233;. Jusqu’&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, peut conf&#233;rer un bonus d’alt&#233;ration de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmement&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Repositionnement.html&quot; title=&quot;repositionnement&quot;&gt;repositionnement&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Subtilisation.html&quot; title=&quot;subtilisation&quot;&gt;subtilisation&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Croc-En-Jambe.html&quot; title=&quot;croc-en-jambe&quot;&gt;croc-en-jambe&lt;/a&gt; effectu&#233;s avec une arme naturelle ou &#224; mains nues.&lt;/td&gt;&lt;td&gt;+7 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Rancune.html&quot; title=&quot;rancune (propri&#233;t&#233;)&quot;&gt;Rancune&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Lorsqu’une attaque au corps &#224; corps port&#233;e dans l’allonge au corps &#224; corps du porteur devrait le faire tomber &#224; moins de 0 points de vie, il peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur#Panache.html&quot; title=&quot;panache&quot;&gt;panache&lt;/a&gt; pour effectuer une attaque au corps &#224; corps contre la cr&#233;ature qui a port&#233;e cette attaque.&lt;/td&gt;&lt;td&gt;+7 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Niche.html&quot; title=&quot;niche (propri&#233;t&#233;)&quot;&gt;Niche&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Peut stocker magiquement un animal ou une cr&#233;ature magique li&#233;(e) au porteur pendant 24 heures maximum (&lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#PACTEAVECLANATURE&quot; title=&quot;Le druide&quot;&gt;compagnon animal&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html#PACTEMAGIQUE&quot; title=&quot;Le magicien&quot;&gt;familier&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html#MONTURE&quot; title=&quot;Le chevalier&quot;&gt;monture&lt;/a&gt;, etc...). La taille maximale de l’animal stockable d&#233;pend de l’objet affect&#233; par cette propri&#233;t&#233;. L’animal stock&#233; peut &#234;tre rel&#226;ch&#233;, auquel cas il agit imm&#233;diatement.&lt;/td&gt;&lt;td&gt;+7 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Sans-Trace.html&quot; title=&quot;sans trace (propri&#233;t&#233;)&quot;&gt;Sans trace&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures en cuir, armures en peau&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;. Les tests de &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; visant &#224; pister le porteur subissent un malus de -5.&lt;/td&gt;&lt;td&gt;+7 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#&#201;clatante.html&quot; title=&quot;&#233;clatante (propri&#233;t&#233;)&quot;&gt;&#201;clatante&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Peut &#233;mettre la m&#234;me lumi&#232;re qu’une &lt;a class=&quot;pagelink&quot; href=&quot;Torche-(Objet).html&quot; title=&quot;Torche&quot;&gt;torche&lt;/a&gt;, &#224; volont&#233;. Une fois par jour, peut &#233;mettre une lumi&#232;re de la m&#234;me intensit&#233; que la lumi&#232;re du jour pendant 1 heure maximum.&lt;/td&gt;&lt;td&gt;+7 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Glissement-De-Phase.html&quot; title=&quot;glissement de phase (propri&#233;t&#233;)&quot;&gt;Glissement de phase&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures l&#233;g&#232;res&lt;/td&gt;&lt;td&gt;Permet a son porteur de traverser les obstacles mat&#233;riels une fois par jour.&lt;/td&gt;&lt;td&gt;+9 100 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Fouisseuse.html&quot; title=&quot;fouisseuse (propri&#233;t&#233;)&quot;&gt;Fouisseuse&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re une vitesse de creusement de 3m dans n’importe quel type de sol. Conf&#232;re un bonus de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les glissements de terrain, les avalanches, les effondrements de tunnels ou tout effet similaire.&lt;/td&gt;&lt;td&gt;+10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Putride.html&quot; title=&quot;putride (propri&#233;t&#233;)&quot;&gt;Putride&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Peut rendre toute les cr&#233;atures vivantes &#224; 9m ou moins du porteur &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#233;vreuses&lt;/a&gt; pendant 5 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;, &#224; volont&#233; (l’effet ne s’estompe compl&#232;tement qu’apr&#232;s une dur&#233;e d&#233;pendant de la zone quand ce pouvoir est d&#233;sactiv&#233;).&lt;/td&gt;&lt;td&gt;+10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Graisseuse-Sup&#233;rieure.html&quot; title=&quot;graisseuse sup&#233;rieure (propri&#233;t&#233;)&quot;&gt;Graisseuse sup&#233;rieure&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +10 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;+15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Harmonique.html&quot; title=&quot;harmonique (propri&#233;t&#233;)&quot;&gt;Harmonique&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt;, mais inflige un malus de -5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; ainsi qu’une vuln&#233;rabilit&#233; aux d&#233;g&#226;ts de son. Prolonge les effets des &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#REPRESENTATIONBARDIQUE&quot; title=&quot;Le barde&quot;&gt;repr&#233;sentations bardiques&lt;/a&gt; du porteur pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; apr&#232;s qu’il les arr&#234;te (non cumulable avec &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation-Obs&#233;dante.html&quot; title=&quot;Repr&#233;sentation obs&#233;dante&quot;&gt;Repr&#233;sentation obs&#233;dante&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;+15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Mange-Venin.html&quot; title=&quot;mange-venin (propri&#233;t&#233;)&quot;&gt;Mange-venin&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures fabriqu&#233;es en cuir&lt;/td&gt;&lt;td&gt;Permet &#224; son porteur de stocker les poisons de cr&#233;atures venimeuses pour empoisonner ses propres armes.&lt;/td&gt;&lt;td&gt;+15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Ombre-Sup&#233;rieure.html&quot; title=&quot;ombre sup&#233;rieure (propri&#233;t&#233;)&quot;&gt;Ombre sup&#233;rieure&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +10 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;+15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Vol-Radieux.html&quot; title=&quot;vol radieux (propri&#233;t&#233;)&quot;&gt;Vol radieux&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures lourdes&lt;/td&gt;&lt;td&gt;Permet de voler &#224; l&#39;aide d&#39;ailes &#233;clairant comme une torche pendant un maximum de 10 minutes par jour.&lt;/td&gt;&lt;td&gt;+15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Martyr.html&quot; title=&quot;martyr (propri&#233;t&#233;)&quot;&gt;Martyr&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Une fois par jour, lorsque le porteur est victime d’un coup critique, il peut rendre 1d8+9 points de vie &#224; 9 alli&#233;s maximum dans un rayon de 9m autour de lui (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soins-L&#233;gers-De-Groupe.html&quot; title=&quot;Soins l&#233;gers de groupe&quot;&gt;soins l&#233;gers de groupe&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;+18 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;r&#233;sistance aux &#233;nergies destructives (propri&#233;t&#233;)&quot;&gt;R&#233;sistance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;L’objet absorbe les 10 premiers points de d&#233;g&#226;ts d’un type d’&#233;nergie choisi &#224; la fabrication de toute attaque subie par le porteur (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;R&#233;sistance aux &#233;nergies destructives&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;+18 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Impie.html&quot; title=&quot;impie (propri&#233;t&#233; armure)&quot;&gt;Impie&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Une fois par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Force-Du-Colosse.html&quot; title=&quot;Force du colosse&quot;&gt;force du colosse&lt;/a&gt;&lt;/i&gt; (&#233;nergie n&#233;gative uniquement) pendant 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. Inflige un &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; aux porteurs d’alignement Bon. &lt;/td&gt;&lt;td&gt;+27 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Libertaire.html&quot; title=&quot;libertaire (propri&#233;t&#233;)&quot;&gt;Libertaire&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Une fois par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Force-Du-Colosse.html&quot; title=&quot;Force du colosse&quot;&gt;force du colosse&lt;/a&gt;&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 5/Loi au lieu de Mal ou Bien) pendant 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. Inflige un &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; aux porteurs d’alignement Loyal. &lt;/td&gt;&lt;td&gt;+27 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Vertueuse.html&quot; title=&quot;vertueuse (propri&#233;t&#233;)&quot;&gt;Vertueuse&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Une fois par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Force-Du-Colosse.html&quot; title=&quot;Force du colosse&quot;&gt;force du colosse&lt;/a&gt;&lt;/i&gt; (&#233;nergie positive uniquement) pendant 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. Inflige un &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; aux porteurs d’alignement Mauvais. &lt;/td&gt;&lt;td&gt;+27 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Vigilante.html&quot; title=&quot;vigilante (propri&#233;t&#233;)&quot;&gt;Vigilante&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Une fois par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Force-Du-Colosse.html&quot; title=&quot;Force du colosse&quot;&gt;force du colosse&lt;/a&gt;&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 5/Chaos au lieu de Mal ou Bien) pendant 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. Inflige un &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; aux porteurs d’alignement Chaotique. &lt;/td&gt;&lt;td&gt;+27 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;termination.html&quot; title=&quot;d&#233;termination (propri&#233;t&#233;)&quot;&gt;D&#233;termination&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Une fois par jour, lorsque le porteur devrait tomber &#224; 0 points de vie ou moins, conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Souffle-De-Vie.html&quot; title=&quot;Souffle de vie&quot;&gt;souffle de vie&lt;/a&gt;&lt;/i&gt;. &lt;/td&gt;&lt;td&gt;+30 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Graisseuse-Supr&#234;me.html&quot; title=&quot;graisseuse supr&#234;me (propri&#233;t&#233;)&quot;&gt;Graisseuse supr&#234;me&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +15 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;+33 750 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Ombre-Supr&#234;me.html&quot; title=&quot;Ombre supr&#234;me (propri&#233;t&#233;)&quot;&gt;Ombre supr&#234;me&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +15 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;+33 750 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-Sup&#233;rieure-Aux-&#201;nergies-Destructives.html&quot; title=&quot;r&#233;sistance sup&#233;rieure aux &#233;nergies destructives (propri&#233;t&#233;)&quot;&gt;R&#233;sistance sup&#233;rieure aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;L’objet absorbe les 20 premiers points de d&#233;g&#226;ts d’un type d’&#233;nergie choisi &#224; la fabrication de toute attaque subie par le porteur (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;R&#233;sistance aux &#233;nergies destructives&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;+42 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Contr&#244;le-Des-Morts-Vivants.html&quot; title=&quot;contr&#244;le des morts-vivants (propri&#233;t&#233;)&quot;&gt;Contr&#244;le des morts-vivants&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Permet de contr&#244;ler jusqu’&#224; 26 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; de morts-vivants par jour (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Des-Morts-Vivants.html&quot; title=&quot;Contr&#244;le des morts-vivants&quot;&gt;contr&#244;le des morts-vivants&lt;/a&gt;&lt;/i&gt;), il en perd le contr&#244;le &#224; l’aube suivant l’utilisation de ce pouvoir.&lt;/td&gt;&lt;td&gt;+49 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#&#201;th&#233;r&#233;e.html&quot; title=&quot;&#233;th&#233;r&#233;e (propri&#233;t&#233;)&quot;&gt;&#201;th&#233;r&#233;e&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-&#201;th&#233;r&#233;e.html&quot; title=&quot;Forme &#233;th&#233;r&#233;e&quot;&gt;forme &#233;th&#233;r&#233;e&lt;/a&gt;&lt;/i&gt; sans limite de dur&#233;e, mais ne pouvant &#234;tre r&#233;activ&#233; qu’apr&#232;s les 24 heures suivants la d&#233;sactivation.&lt;/td&gt;&lt;td&gt;+49 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-Supr&#234;me-Aux-&#201;nergies-Destructives.html&quot; title=&quot;r&#233;sistance supr&#234;me aux &#233;nergies destructives (propri&#233;t&#233;)&quot;&gt;R&#233;sistance supr&#234;me aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;L’objet absorbe les 30 premiers points de d&#233;g&#226;ts d’un type d’&#233;nergie choisi &#224; la fabrication de toute attaque subie par le porteur (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;R&#233;sistance aux &#233;nergies destructives&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;+66 000 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Propri&#233;t&#233;s ajoutant un bonus de +1&lt;a class=&quot;headeranchor&quot; id=&quot;Propri&#233;t&#233;s_ajoutant_un_bonus_de_+B_1&quot; href=&quot;#Propri&#233;t&#233;s_ajoutant_un_bonus_de_+B_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche&quot; WIDTH=&quot;100%&quot;&gt;&lt;caption&gt;Propri&#233;t&#233;s ajoutant un bonus de +1&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;12%&quot;&gt;Propri&#233;t&#233;&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;11%&quot;&gt;Restrictions&lt;/td&gt;&lt;td WIDTH=&quot;61%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;13%&quot;&gt;Modificateur au prix de base&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Amertume.html&quot; title=&quot;amertume (propri&#233;t&#233;)&quot;&gt;Amertume&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Peut faire l&#226;cher prise aux cr&#233;atures qui &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Agripp&#233;.html&quot; title=&quot;Agripp&#233;&quot;&gt;agrippent&lt;/a&gt; le porteur avec une attaque de morsure, de bouche ou de gueule. Peut rendre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Naus&#233;eux.html&quot; title=&quot;Naus&#233;eux&quot;&gt;naus&#233;euses&lt;/a&gt; les cr&#233;atures qui &lt;a class=&quot;pagelink&quot; href=&quot;Engloutissement-(Capacit&#233;).html&quot; title=&quot;Engloutissement (Ext)&quot;&gt;engloutissent&lt;/a&gt; le porteur.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Apaisante.html&quot; title=&quot;apaisante (propri&#233;t&#233;)&quot;&gt;Apaisante&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, peut apaiser les &#233;motions des cr&#233;atures hostiles dans un rayon de 1,5m autour du porteur (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Apaisement-Des-&#201;motions.html&quot; title=&quot;Apaisement des &#233;motions&quot;&gt;apaisement des &#233;motions&lt;/a&gt;&lt;/i&gt;) et qui peut mettre fin &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGE&quot; title=&quot;Le barbare&quot;&gt;rage&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Assidu.html&quot; title=&quot;assidu (propri&#233;t&#233;)&quot;&gt;Assidu&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers&lt;/td&gt;&lt;td&gt;Prot&#232;ge le porteur des &lt;a class=&quot;pagelink&quot; href=&quot;Regard-(Capacit&#233;).html&quot; title=&quot;Regard (Sur)&quot;&gt;attaques de regard&lt;/a&gt; quand il &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Combatsurladefensive.html&quot; title=&quot;combat sur la d&#233;fensive&quot;&gt;combat sur la d&#233;fensive&lt;/a&gt; ou utilise l&#39;action &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Defensetotale.html&quot; title=&quot;d&#233;fense totale&quot;&gt;d&#233;fense totale&lt;/a&gt;, et peut renvoyer ces attaques &#224; leur source.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Attaque.html&quot; title=&quot;attaque (propri&#233;t&#233;)&quot;&gt;Attaque&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&#201;cus, rondaches&lt;/td&gt;&lt;td&gt;Inflige des d&#233;g&#226;ts comme s’il &#233;tait de deux cat&#233;gories de taille de plus. Poss&#232;de un &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#BONUSDALTERATION&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;bonus d’alt&#233;ration&lt;/a&gt; de +1 lorsqu’on attaque avec.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Aveuglante.html&quot; title=&quot;aveuglante (propri&#233;t&#233;)&quot;&gt;Aveuglante&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers&lt;/td&gt;&lt;td&gt;Deux fois par jour, peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Aveugl&#233;.html&quot; title=&quot;Aveugl&#233;&quot;&gt;aveugler&lt;/a&gt; toutes les cr&#233;atures dans un rayon de 6m du porteur pendant 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round(s)&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Barbel&#233;e.html&quot; title=&quot;barbel&#233;e (propri&#233;t&#233;)&quot;&gt;Barbel&#233;e&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Inflige un nombre de points de d&#233;g&#226;ts &#233;gal au bonus d’alt&#233;ration de l’objet aux cr&#233;atures qui tente de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutter&lt;/a&gt; contre le porteur ou de l’&lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;immobiliser&lt;/a&gt;. L’objet est consid&#233;r&#233; comme poss&#233;dant des pointes d’armure.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#B&#233;lier.html&quot; title=&quot;b&#233;lier (propri&#233;t&#233;)&quot;&gt;B&#233;lier&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers&lt;/td&gt;&lt;td&gt;Lors d’une charge avec l’objet, le porteur ajoute son bonus d’alt&#233;ration aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt;. Permet d’effectuer une manœuvre de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Bousculade.html&quot; title=&quot;bousculade&quot;&gt;bousculade&lt;/a&gt; avec un bonus &#233;gal au bonus d’alt&#233;ration du bouclier + 2 par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; au touch&#233;.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Blasonn&#233;.html&quot; title=&quot;blasonn&#233; (propri&#233;t&#233;)&quot;&gt;Blasonn&#233;&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&#201;cus et pavois&lt;/td&gt;&lt;td&gt;Compte comme une &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html#BANNIERE&quot; title=&quot;Le chevalier&quot;&gt;banni&#232;re de chevalier&lt;/a&gt; et comme un &lt;a class=&quot;pagelink&quot; href=&quot;Symbole-Sacr&#233;-(Objet).html&quot; title=&quot;Symbole sacr&#233;&quot;&gt;symbole sacr&#233;&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Championne.html&quot; title=&quot;championne (propri&#233;t&#233;)&quot;&gt;Championne&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re &#224; un porteur Bon avec la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html#DEFI&quot; title=&quot;Le chevalier&quot;&gt;d&#233;fi&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CHATIMENTDUMAL&quot; title=&quot;Le paladin&quot;&gt;ch&#226;timent du Mal&lt;/a&gt; un bonus de saintet&#233; de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; contre les attaques de l’adversaire d&#233;sign&#233; par ces capacit&#233;s.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Croisades.html&quot; title=&quot;croisades (propri&#233;t&#233;)&quot;&gt;Croisades&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Combattant.html&quot; title=&quot;Le pr&#234;tre combattant&quot;&gt;pr&#234;tre combattant&lt;/a&gt; Bon peut d&#233;penser une utilisation d’&lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#IMPOSITIONDESMAINS&quot; title=&quot;Le paladin&quot;&gt;imposition des mains&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Combattant.html#FERVEUR&quot; title=&quot;Le pr&#234;tre combattant&quot;&gt;ferveur&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; pour obtenir un bonus de saintet&#233; de +2  &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; pendant 1 minute (le bonus passe &#224; +3 contre les dragons Mauvais, les ext&#233;rieurs Mauvais et les morts-vivants).&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;chire-Sort.html&quot; title=&quot;d&#233;chire-sort (propri&#233;t&#233;)&quot;&gt;D&#233;chire-sort&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers de &lt;i&gt;r&#233;sistance &#224; la magie&lt;/i&gt;&lt;/td&gt;&lt;td&gt;Stocke l&#39;&#233;nergie des sorts absorb&#233;s gr&#226;ce &#224; la propri&#233;t&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-&#192;-La-Magie-(13).html&quot; title=&quot;r&#233;sistance &#224; la magie 13 (propri&#233;t&#233;)&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt;&lt;/i&gt; pour offrir un bonus aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; d&#39;un coup de bouclier.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;fense-(L&#233;g&#232;re).html&quot; title=&quot;d&#233;fense l&#233;g&#232;re (propri&#233;t&#233;)&quot;&gt;D&#233;fense (l&#233;g&#232;re)&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Le porteur a 25 % de chances d’ignorer les d&#233;g&#226;ts suppl&#233;mentaires inflig&#233;s par les coups critiques et les attaques sournoises.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Environnementale.html&quot; title=&quot;environnementale (propri&#233;t&#233;)&quot;&gt;Environnementale&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures interm&#233;diaires&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d&#39;alt&#233;ration de +3 m&#232;tres &#224; sa vitesse sur un terrain sp&#233;cifique et r&#233;duit le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Malusarmure.html&quot; title=&quot;malus d&amp;#39;armure&quot;&gt;malus d&#39;armure&lt;/a&gt; aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; et d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; effectu&#233;s sur ce terrain.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#&#201;quilibr&#233;e.html&quot; title=&quot;&#233;quilibr&#233;e (propri&#233;t&#233;)&quot;&gt;&#201;quilibr&#233;e&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures l&#233;g&#232;res et interm&#233;diaires&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +4 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre les manœuvres de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Renversement.html&quot; title=&quot;renversement&quot;&gt;renversement&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Croc-En-Jambe.html&quot; title=&quot;croc-en-jambe&quot;&gt;croc-en-jambe&lt;/a&gt;, ainsi qu’aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; pour &#233;viter de tomber. &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Libres.html#PLONGERAUSOL&quot; title=&quot;Actions libres&quot;&gt;Plonger au sol&lt;/a&gt; co&#251;te une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; au porteur.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#&#201;quilibr&#233;e-Amh.html&quot; title=&quot;&#233;quilibr&#233;e AMH (propri&#233;t&#233;)&quot;&gt;&#201;quilibr&#233;e (AMH)&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures interm&#233;diaires&lt;/td&gt;&lt;td&gt;Permet au porteur de distribuer le bonus d&#39;alt&#233;ration de l&#39;armure entre sa CA et un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; choisit &#224; la cr&#233;ation.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Fourberie.html&quot; title=&quot;fourberie (propri&#233;t&#233;)&quot;&gt;Fourberie&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re &#224; un porteur Mauvais avec la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html#DEFI&quot; title=&quot;Le chevalier&quot;&gt;d&#233;fi&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CHATIMENTDUBIEN&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;ch&#226;timent du Bien&lt;/a&gt; un bonus de malfaisance de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; contre les attaques de l’adversaire d&#233;sign&#233; par ces capacit&#233;s.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Garrot.html&quot; title=&quot;garrot (propri&#233;t&#233;)&quot;&gt;Garrot&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Tous les d&#233;g&#226;ts de saignement subit par le porteur sont r&#233;duit d’un montant &#233;gal au bonus d’alt&#233;ration de l’objet. Conf&#232;re un bonus &#233;gal au bonus d’alt&#233;ration de l’objet aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; du porteur pour se stabiliser.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Immortalit&#233;.html&quot; title=&quot;immortalit&#233; (propri&#233;t&#233;)&quot;&gt;Immortalit&#233;&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;L’objet absorbe les 10 premiers points de d&#233;g&#226;ts d’&#233;nergie positive ou n&#233;gative de toute attaque subie par le porteur (sauf les soins). Le porteur a 25 % de chances d’ignorer les attaques infligeant des &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveaux n&#233;gatifs&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Interception-De-Projectile.html&quot; title=&quot;interception de projectile (propri&#233;t&#233;)&quot;&gt;Interception de projectile&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de parade de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; contre les armes &#224; distance. Toute arme de jet ou projectile qui vise une cible situ&#233;e &#224; 1,5m ou moins du porteur le visent &#224; la place. Les attaques &#224; distance ne subissent jamais de chance d’&#233;chec lorsqu’elles visent le porteur. Les effets de cette propri&#233;t&#233; peuvent &#234;tre d&#233;sactiv&#233;s &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Miroir.html&quot; title=&quot;miroir (propri&#233;t&#233;)&quot;&gt;Miroir&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers et armures m&#233;talliques&lt;/td&gt;&lt;td&gt;Le bonus d’alt&#233;ration de l’objet s’ajoute &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; au contact du porteur contre les rayons. Lorsqu’il d&#233;tourne le regard d’une &lt;a class=&quot;pagelink&quot; href=&quot;Regard-(Capacit&#233;).html&quot; title=&quot;Regard (Sur)&quot;&gt;attaque de regard&lt;/a&gt;, le porteur lance 2 d&#233;s d’&#233;vitement et conserve le meilleur r&#233;sultat. Permet d’infliger des d&#233;g&#226;ts de pr&#233;cisions aux cr&#233;atures qui b&#233;n&#233;ficient d’un camouflage contre le porteur dus au d&#233;tournement de regard.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Opposition.html&quot; title=&quot;opposition (propri&#233;t&#233;)&quot;&gt;Opposition&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;L’objet conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 2/- et voit son bonus d’alt&#233;ration &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; augmenter de 2 contre un type de cr&#233;ature choisi &#224; la fabrication.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Placement.html&quot; title=&quot;placement (propri&#233;t&#233; armure)&quot;&gt;Placement&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures lourdes&lt;/td&gt;&lt;td&gt;Permet de se d&#233;placer de 3 m&#232;tres apr&#232;s avoir r&#233;duit un adversaire &#224; 0 &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;point de vie&quot;&gt;pv&lt;/a&gt; ou moins avec une attaque de corps &#224; corps.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Pliant.html&quot; title=&quot;pliant (propri&#233;t&#233;)&quot;&gt;Pliant&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers&lt;/td&gt;&lt;td&gt;Le bouclier peut se changer en &lt;a class=&quot;pagelink&quot; href=&quot;Targe-(Armure).html&quot; title=&quot;Targe&quot;&gt;targe&lt;/a&gt;, en &lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu&lt;/a&gt; et en &lt;a class=&quot;pagelink&quot; href=&quot;Pavois-(Armure).html&quot; title=&quot;Pavois&quot;&gt;pavois&lt;/a&gt; sur commande.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Pr&#233;vention.html&quot; title=&quot;pr&#233;vention (propri&#233;t&#233;)&quot;&gt;Pr&#233;vention&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Une fois par jour, le porteur peut, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;, mettre fin &#224; tout les &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html#DEFI&quot; title=&quot;Le chevalier&quot;&gt;d&#233;fis&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#JUGEMENT&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;jugements&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CHATIMENTDUMAL&quot; title=&quot;Le paladin&quot;&gt;ch&#226;timents&lt;/a&gt; qui l’affectent. Un porteur avec l’une de ces capacit&#233;s peut activer ce pouvoir par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; autant de fois qu’il le souhaite en en d&#233;pensant une utilisation.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Protection.html&quot; title=&quot;protection (propri&#233;t&#233;)&quot;&gt;Protection&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers&lt;/td&gt;&lt;td&gt;Le porteur peut distribuer le bonus d’alt&#233;ration du bouclier entre sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et celle d&#39;un alli&#233; adjacent &#224; chaque tour.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Protection-Contre-Les-Pi&#232;ges.html&quot; title=&quot;protection contre les pi&#232;ges (propri&#233;t&#233;)&quot;&gt;Protection contre les pi&#232;ges&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de chance &#233;gal au bonus d&#39;alt&#233;ration aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Pi&#232;ges.html&quot; title=&quot;Les pi&#232;ges&quot;&gt;pi&#232;ges&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Renforcement.html&quot; title=&quot;renforcement (propri&#233;t&#233;)&quot;&gt;Renforcement&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures interm&#233;diaires et lourdes, rondaches, &#233;cus, pavois&lt;/td&gt;&lt;td&gt;&#192; chaque fois que le porteur inflige des d&#233;g&#226;ts &#224; une cr&#233;ature gr&#226;ce &#224; une attaque &#224; distance ou au corps &#224; corps, conf&#232;re un bonus de comp&#233;tence de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre ses capacit&#233;s jusqu’au d&#233;but du prochain &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sonance.html&quot; title=&quot;r&#233;sonance (propri&#233;t&#233;)&quot;&gt;R&#233;sonance&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Trois fois par jour, quand le porteur d&#233;pense une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, le bonus d’alt&#233;ration de l’armure augmente de 2 et les &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; du porteur augmentent de 5, pendant un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; &#233;gal au &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade&lt;/a&gt; du porteur.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Retentissant.html&quot; title=&quot;retentissant (propri&#233;t&#233;)&quot;&gt;Retentissant&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Lorsque le porteur est touch&#233; par une attaque, peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Assourdi.html&quot; title=&quot;Assourdi&quot;&gt;assourdir&lt;/a&gt; les cr&#233;atures autour de lui (comme avec une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Alchimiques.html#Pierre tonnerre&quot; title=&quot;Armes alchimiques&quot;&gt;pierre tonnerre&lt;/a&gt;), ou si l’attaque est un coup critique, manifester les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cacophonie.html&quot; title=&quot;Cacophonie&quot;&gt;cacophonie&lt;/a&gt;&lt;/i&gt; (le rayon de ces effets est au choix du porteur mais doit comprendre l’attaquant).&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Sauvegarde.html&quot; title=&quot;sauvegarde (propri&#233;t&#233;)&quot;&gt;Sauvegarde&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt;/5 au porteur tant qu’il est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;inconscient&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Naus&#233;eux.html&quot; title=&quot;Naus&#233;eux&quot;&gt;naus&#233;eux&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;tourdi.html&quot; title=&quot;&#201;tourdi&quot;&gt;&#233;tourdi&lt;/a&gt; (et qu’il de peut pas effectuer d’&lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; dans ces &#233;tats) ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Immobilis&#233;.html&quot; title=&quot;Immobilis&#233;&quot;&gt;immobilis&#233;&lt;/a&gt; (et qu’il ne peut pas attaquer dans cet &#233;tat).&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Solide.html&quot; title=&quot;solide (propri&#233;t&#233; armure)&quot;&gt;Solide&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Ajoute le double du bonus d’alt&#233;ration de l’objet &#224; sa solidit&#233; et &#224; ses points de r&#233;sistance. Conf&#232;re un bonus du m&#234;me montant au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; pour briser l’objet et aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les attaques port&#233;es &#224; l’objet.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Soutien.html&quot; title=&quot;soutien (propri&#233;t&#233; armure)&quot;&gt;Soutien&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Ajoute le bonus d’alt&#233;ration de l’armure au bonus conf&#233;r&#233; par l’action &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales.html#AIDERQQN&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;aider quelqu’un&lt;/a&gt; lorsqu’elle est utilis&#233;e pour am&#233;liorer la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Stockage-De-Sort.html&quot; title=&quot;stockage de sort (propri&#233;t&#233; armure)&quot;&gt;Stockage de sort&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;L’armure peut stocker un sort du 3e niveau ou moins que le porteur peut livrer d&#232;s qu’il est touch&#233; par une attaque au corps &#224; corps ou au contact.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Tenace.html&quot; title=&quot;tenace (propri&#233;t&#233;)&quot;&gt;Tenace&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures interm&#233;diaires&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d&#39;alt&#233;ration de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; li&#233;s a un type de cr&#233;ature choisi &#224; la cr&#233;ation et a 50 % de chances d’annuler les d&#233;g&#226;ts suppl&#233;mentaires inflig&#233;s par les coups critiques et les attaques sournoises de ce type de cr&#233;ature.&lt;/td&gt;&lt;td&gt;bonus de +1&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Propri&#233;t&#233;s ajoutant un bonus de +2&lt;a class=&quot;headeranchor&quot; id=&quot;Propri&#233;t&#233;s_ajoutant_un_bonus_de_+C_2&quot; href=&quot;#Propri&#233;t&#233;s_ajoutant_un_bonus_de_+C_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche&quot; WIDTH=&quot;100%&quot;&gt;&lt;caption&gt;Propri&#233;t&#233;s ajoutant un bonus de +2&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;12%&quot;&gt;Propri&#233;t&#233;&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;11%&quot;&gt;Restrictions&lt;/td&gt;&lt;td WIDTH=&quot;61%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;13%&quot;&gt;Modificateur au prix de base&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Anim&#233;e.html&quot; title=&quot;anim&#233;e (propri&#233;t&#233;)&quot;&gt;Anim&#233;e&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers (sauf pavois)&lt;/td&gt;&lt;td&gt;Par une action simple, le porteur peut l&#226;cher le bouclier pour qu’il s’anime et le prot&#232;ge comme s’il le tenait pendant 4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; avant de tomber &#224; terre. Anim&#233;, il peut activer seul toute propri&#233;t&#233; sp&#233;ciale ne n&#233;cessitant pas d’action. L’activateur peut le reprendre en main par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; (il doit alors attendre 4 rounds pour l’activer de nouveau) .&lt;/td&gt;&lt;td&gt;bonus de +2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Anti-Projectiles.html&quot; title=&quot;anti-projectiles (propri&#233;t&#233;)&quot;&gt;Anti-projectiles&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers&lt;/td&gt;&lt;td&gt;Une fois par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, peut d&#233;tourner une attaque &#224; distance sans d&#233;penser d’action (comme avec &lt;a class=&quot;pagelink&quot; href=&quot;Parade-De-Projectiles.html&quot; title=&quot;Parade de projectiles&quot;&gt;Parade de projectiles&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;bonus de +2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Esquive-Des-Sorts.html&quot; title=&quot;esquive des sorts (propri&#233;t&#233;)&quot;&gt;Esquive des sorts&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’esquive de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; des sorts, des pouvoirs magiques et des attaques de cr&#233;atures invoqu&#233;es.&lt;/td&gt;&lt;td&gt;bonus de +2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Fumante.html&quot; title=&quot;fumante (propri&#233;t&#233;)&quot;&gt;Fumante&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures interm&#233;diaires et lourdes&lt;/td&gt;&lt;td&gt;Trois fois par jour, peut &#233;mettre une vapeur qui inflige des d&#233;g&#226;ts aux cr&#233;atures en lutte et autour du porteur pendant 5 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;bonus de +2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Fusion.html&quot; title=&quot;fusion (propri&#233;t&#233;)&quot;&gt;Fusion&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&#201;cus, rondaches&lt;/td&gt;&lt;td&gt;Peut fusionner avec une arme l&#233;g&#232;re ou &#224; une main tenue en main. Fusionn&#233;, le porteur choisi &#224; chaque &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; s’il veut attaquer (ce qui lui fait perdre le bonus &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; du bouclier) ou se d&#233;fendre.&lt;/td&gt;&lt;td&gt;bonus de +2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Imaginaire.html&quot; title=&quot;imaginaire (propri&#233;t&#233;)&quot;&gt;Imaginaire&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures l&#233;g&#232;res&lt;/td&gt;&lt;td&gt;Trois fois par jour, peut laisser un double illusoire mena&#231;ant dans une case pr&#233;c&#233;demment occup&#233;e par le porteur.&lt;/td&gt;&lt;td&gt;bonus de +2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Ma&#238;trise.html&quot; title=&quot;ma&#238;trise (propri&#233;t&#233;)&quot;&gt;Ma&#238;trise&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers&lt;/td&gt;&lt;td&gt;Applique le bonus d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armes&lt;/a&gt; le plus &#233;lev&#233; ainsi que la &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#MAITRISEDESARMES&quot; title=&quot;Le guerrier&quot;&gt;ma&#238;trise des armes&lt;/a&gt; du porteur aux coups de bouclier.&lt;/td&gt;&lt;td&gt;bonus de +2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Protection-Sup&#233;rieure.html&quot; title=&quot;protection sup&#233;rieure (propri&#233;t&#233;)&quot;&gt;Protection sup&#233;rieure&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers&lt;/td&gt;&lt;td&gt;Le porteur peut distribuer le bonus d’alt&#233;ration du bouclier entre sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et celle des alli&#233;s adjacents &#224; chaque tour (ils re&#231;oivent tous le m&#234;me bonus).&lt;/td&gt;&lt;td&gt;bonus de +2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Ravageuse.html&quot; title=&quot;ravageuse (propri&#233;t&#233;)&quot;&gt;Ravageuse&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures lourdes&lt;/td&gt;&lt;td&gt; Le porteur ignore les terrains difficiles quand il &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales#Charge.html&quot; title=&quot;charge&quot;&gt;charge&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Bousculade.html&quot; title=&quot;bousculade&quot;&gt;bouscule&lt;/a&gt;. Une fois par jour, permet de transformer la trajectoire d&#39;une charge ou d&#39;une bousculade en terrain difficile.&lt;/td&gt;&lt;td&gt;bonus de +2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-&#192;-La-Magie-(13).html&quot; title=&quot;r&#233;sistance &#224; la magie 13 (propri&#233;t&#233;)&quot;&gt;R&#233;sistance &#224; la magie (13)&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;RM&quot;&gt;RM&lt;/a&gt; de 13.&lt;/td&gt;&lt;td&gt;bonus de +2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Vibrante.html&quot; title=&quot;vibrante (propri&#233;t&#233;)&quot;&gt;Vibrante&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Trois fois par jour, lorsque le porteur est touch&#233; par une attaque au corps &#224; corps effectu&#233;e avec une arme, peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#H&#233;b&#233;t&#233;.html&quot; title=&quot;H&#233;b&#233;t&#233;&quot;&gt;h&#233;b&#233;ter&lt;/a&gt; l’attaquant pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;bonus de +2&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Propri&#233;t&#233;s ajoutant un bonus de +3&lt;a class=&quot;headeranchor&quot; id=&quot;Propri&#233;t&#233;s_ajoutant_un_bonus_de_+D_3&quot; href=&quot;#Propri&#233;t&#233;s_ajoutant_un_bonus_de_+D_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche&quot; WIDTH=&quot;100%&quot;&gt;&lt;caption&gt;Propri&#233;t&#233;s ajoutant un bonus de +3&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;12%&quot;&gt;Propri&#233;t&#233;&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;11%&quot;&gt;Restrictions&lt;/td&gt;&lt;td WIDTH=&quot;61%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;13%&quot;&gt;Modificateur au prix de base&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Collecte-Fl&#232;che.html&quot; title=&quot;collecte-fl&#232;che (propri&#233;t&#233;)&quot;&gt;Collecte-fl&#232;che&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures interm&#233;diaires&lt;/td&gt;&lt;td&gt;Les attaques de projectile &#224; distance ont 20 % de chances de rater le porteur et et celles qui le ratent &#224; cause de cet effet peuvent &#234;tre collect&#233;es et renvoy&#233;es plus tard par le porteur.&lt;/td&gt;&lt;td&gt;bonus de +3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;fense-(Interm&#233;diaire).html&quot; title=&quot;d&#233;fense interm&#233;diaire (propri&#233;t&#233;)&quot;&gt;D&#233;fense (interm&#233;diaire)&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Le porteur a 50 % de chances d’ignorer les d&#233;g&#226;ts suppl&#233;mentaires inflig&#233;s par les coups critiques et les attaques sournoises.&lt;/td&gt;&lt;td&gt;bonus de +3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;viation.html&quot; title=&quot;d&#233;viation (propri&#233;t&#233;)&quot;&gt;D&#233;viation&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers en acier&lt;/td&gt;&lt;td&gt;Trois fois par jour, peut conf&#233;rer un bonus de parade &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; &#233;gal au bonus d’alt&#233;ration du bouclier au porteur et &#224; ses alli&#233;s dans un rayon de 3m, pendant 1 minute (le porteur peut d&#233;penser une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; pour augmenter le bonus de parade d’un montant &#233;gal &#224; la moiti&#233; de son &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;bonus de +3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Forme-Animale.html&quot; title=&quot;forme animale (propri&#233;t&#233;)&quot;&gt;Forme animale&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Le porteur conserve son bonus d’armure (et son bonus d’alt&#233;ration &#224; l’armure) lorsqu’il utilise la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#FORMEANIMALE&quot; title=&quot;Le druide&quot;&gt;forme animale&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;bonus de +3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Invuln&#233;rabilit&#233;.html&quot; title=&quot;invuln&#233;rabilit&#233; (propri&#233;t&#233;)&quot;&gt;Invuln&#233;rabilit&#233;&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 5/magie.&lt;/td&gt;&lt;td&gt;bonus de +3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Perception.html&quot; title=&quot;perception (propri&#233;t&#233;)&quot;&gt;Perception&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Tant que le porteur est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Aveugl&#233;.html&quot; title=&quot;Aveugl&#233;&quot;&gt;aveugl&#233;&lt;/a&gt;, dans des t&#233;n&#232;bres compl&#232;tes (sauf s’il poss&#232;de la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; ou la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Les-T&#233;n&#232;bres-(Capacit&#233;).html&quot; title=&quot;Vision dans les t&#233;n&#232;bres&quot;&gt;vision dans les t&#233;n&#232;bres&lt;/a&gt;) ou dans des t&#233;n&#232;bres magiques (sauf s’il poss&#232;de la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Les-T&#233;n&#232;bres-(Capacit&#233;).html&quot; title=&quot;Vision dans les t&#233;n&#232;bres&quot;&gt;vision dans les t&#233;n&#232;bres&lt;/a&gt;), conf&#232;re la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Aveugle-(Capacit&#233;).html&quot; title=&quot;Vision aveugle (Ext)&quot;&gt;vision aveugle&lt;/a&gt; (1,5m) et la &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Aveugle-(Capacit&#233;).html&quot; title=&quot;Perception aveugle (Ext)&quot;&gt;perception aveugle&lt;/a&gt; (18m).&lt;/td&gt;&lt;td&gt;bonus de +3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Pugilat.html&quot; title=&quot;pugilat (propri&#233;t&#233;)&quot;&gt;Pugilat&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures l&#233;g&#232;res&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; &#224; mains nues et aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt;. Les attaques &#224; mains nues du porteur sont consid&#233;r&#233;s comme des armes magiques.&lt;/td&gt;&lt;td&gt;bonus de +3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-&#192;-La-Magie-(15).html&quot; title=&quot;r&#233;sistance &#224; la magie 15 (propri&#233;t&#233;)&quot;&gt;R&#233;sistance &#224; la magie (15)&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;RM&quot;&gt;RM&lt;/a&gt; de 15.&lt;/td&gt;&lt;td&gt;bonus de +3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Spectrale.html&quot; title=&quot;spectrale (propri&#233;t&#233; armure)&quot;&gt;Spectrale&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;L’armure est consid&#233;r&#233;e comme tangible et intangible &#224; tout moment.&lt;/td&gt;&lt;td&gt;bonus de +3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Titanesque.html&quot; title=&quot;titanesque (propri&#233;t&#233;)&quot;&gt;Titanesque&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;Le porteur est consid&#233;r&#233; comme &#233;tant d’une cat&#233;gorie de taille de plus &#224; tout moment. Une fois par jour, peut augmenter la taille du porteur d’une cat&#233;gorie pendant 1 minute (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Agrandissement.html&quot; title=&quot;Agrandissement&quot;&gt;agrandissement&lt;/a&gt;&lt;/i&gt;). Une fois par minute, peut ajouter le bonus d’alt&#233;ration de l’armure &#224; un test de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Bmo.html&quot; title=&quot;BMO&quot;&gt;BMO&lt;/a&gt; ou au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; du porteur. Augmente le malus d’armure aux tests de l’armure du m&#234;me montant.&lt;/td&gt;&lt;td&gt;bonus de +3&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Propri&#233;t&#233;s ajoutant un bonus de +4&lt;a class=&quot;headeranchor&quot; id=&quot;Propri&#233;t&#233;s_ajoutant_un_bonus_de_+E_4&quot; href=&quot;#Propri&#233;t&#233;s_ajoutant_un_bonus_de_+E_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche&quot; WIDTH=&quot;100%&quot;&gt;&lt;caption&gt;Propri&#233;t&#233;s ajoutant un bonus de +4&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;12%&quot;&gt;Propri&#233;t&#233;&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;11%&quot;&gt;Restrictions&lt;/td&gt;&lt;td WIDTH=&quot;61%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;13%&quot;&gt;Modificateur au prix de base&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#N&#233;gation.html&quot; title=&quot;n&#233;gation (propri&#233;t&#233;)&quot;&gt;N&#233;gation&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures lourdes&lt;/td&gt;&lt;td&gt;Une fois par jour, peut annuler les d&#233;g&#226;ts suppl&#233;mentaires d’un &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coup critique&lt;/a&gt; ou d’une &lt;a class=&quot;pagelink&quot; href=&quot;Roublard#Attaquesournoise.html&quot; title=&quot;attaque sournoise&quot;&gt;attaque sournoise&lt;/a&gt; subie par le porteur (le porteur peut d&#233;penser deux utilisations de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; pour utiliser ce pouvoir plus d’une fois par jour).&lt;/td&gt;&lt;td&gt;bonus de +4&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Rempart.html&quot; title=&quot;rempart (propri&#233;t&#233;)&quot;&gt;Rempart&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&#201;cus et pavois&lt;/td&gt;&lt;td&gt;Chaque fois que le porteur &#233;choue un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; contre un effet mental, le bouclier neutralise cet effet pendant un nombre de rounds &#233;gal &#224; son bonus d&#39;alt&#233;ration.&lt;/td&gt;&lt;td&gt;bonus de +4&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-&#192;-La-Magie-(17).html&quot; title=&quot;r&#233;sistance &#224; la magie 17 (propri&#233;t&#233;)&quot;&gt;R&#233;sistance &#224; la magie (17)&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;RM&quot;&gt;RM&lt;/a&gt; de 17.&lt;/td&gt;&lt;td&gt;bonus de +4&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Propri&#233;t&#233;s ajoutant un bonus de +5&lt;a class=&quot;headeranchor&quot; id=&quot;Propri&#233;t&#233;s_ajoutant_un_bonus_de_+F_5&quot; href=&quot;#Propri&#233;t&#233;s_ajoutant_un_bonus_de_+F_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche&quot; WIDTH=&quot;100%&quot;&gt;&lt;caption&gt;Propri&#233;t&#233;s ajoutant un bonus de +5&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;12%&quot;&gt;Propri&#233;t&#233;&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;11%&quot;&gt;Restrictions&lt;/td&gt;&lt;td WIDTH=&quot;61%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;13%&quot;&gt;Modificateur au prix de base&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Aile-D&#39;effroi.html&quot; title=&quot;aile d&amp;#39;effroi (propri&#233;t&#233;)&quot;&gt;Aile d&#39;effroi&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Harnois et armures de L&#233;gionnaire infernal&lt;/td&gt;&lt;td&gt;L&#39;armure peut se transformer en ailes de dragon, r&#233;duisant son bonus d&#39;armure de moiti&#233; mais permettant au porteur de voler et de porter deux attaques naturelles secondaires d&#39;aile.&lt;/td&gt;&lt;td&gt;bonus de +5&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;fense-(Lourde).html&quot; title=&quot;d&#233;fense lourde (propri&#233;t&#233;)&quot;&gt;D&#233;fense (lourde)&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Le porteur a 75 % de chances d’ignorer les d&#233;g&#226;ts suppl&#233;mentaires inflig&#233;s par les coups critiques et les attaques sournoises.&lt;/td&gt;&lt;td&gt;bonus de +5&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Inflexible.html&quot; title=&quot;inflexible (propri&#233;t&#233;)&quot;&gt;Inflexible&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;AMH&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Armures lourdes&lt;/td&gt;&lt;td&gt;Annule les prochains d&#233;g&#226;ts qui devraient r&#233;duire les points de vie du porteur &#224; 0 ou moins, ce qui d&#233;truit l&#39;armure et inflige des d&#233;g&#226;ts perforants aux cr&#233;atures dans un rayon de 3 m.&lt;/td&gt;&lt;td&gt;bonus de +5&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;fl&#233;chissante.html&quot; title=&quot;r&#233;fl&#233;chissante (propri&#233;t&#233;)&quot;&gt;R&#233;fl&#233;chissante&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Boucliers&lt;/td&gt;&lt;td&gt;Une fois par jour, peut renvoyer un sort qui le cible au lanceur (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Renvoi-Des-Sorts.html&quot; title=&quot;Renvoi des sorts&quot;&gt;renvoi des sorts&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;bonus de +5&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-&#192;-La-Magie-(19).html&quot; title=&quot;r&#233;sistance &#224; la magie 19 (propri&#233;t&#233;)&quot;&gt;R&#233;sistance &#224; la magie (19)&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;RM&quot;&gt;RM&lt;/a&gt; de 19.&lt;/td&gt;&lt;td&gt;bonus de +5&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
